DROP TABLE IF EXISTS `product_skus`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_skus` (
  `id` int NOT NULL AUTO_INCREMENT,
  `spec_id` int NOT NULL,
  `color_id` int NOT NULL,
  `current_stock` int DEFAULT '0',
  `low_stock_threshold` int DEFAULT '50',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_spec_color` (`spec_id`,`color_id`),
  KEY `color_id` (`color_id`),
  CONSTRAINT `product_skus_ibfk_1` FOREIGN KEY (`spec_id`) REFERENCES `product_specs` (`id`),
  CONSTRAINT `product_skus_ibfk_2` FOREIGN KEY (`color_id`) REFERENCES `colors` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=81 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

