--
-- Table structure for table `salary_records`
--

DROP TABLE IF EXISTS `salary_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `salary_records` (
  `id` int NOT NULL AUTO_INCREMENT,
  `worker_id` int NOT NULL,
  `month` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '日期',
  `spec_name` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `color_name` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `item_name` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工序',
  `quantity` int DEFAULT NULL COMMENT '数量',
  `unit_price` decimal(10,2) DEFAULT NULL COMMENT '单价(可手动修改)',
  `amount` decimal(10,2) DEFAULT NULL COMMENT '金额=数量×单价',
  `payment_method` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '支付方式',
  `paid` int DEFAULT NULL COMMENT '0未付/1已付',
  `remark` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `worker_id` (`worker_id`),
  KEY `idx_salary_month` (`month`),
  CONSTRAINT `salary_records_ibfk_1` FOREIGN KEY (`worker_id`) REFERENCES `salary_workers` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=475 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

