DROP TABLE IF EXISTS `salary_spec_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `salary_spec_items` (
  `id` int NOT NULL AUTO_INCREMENT,
  `spec_name` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产品规格',
  `item_name` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工序名称',
  `unit_price` decimal(10,2) DEFAULT '0.00',
  `is_active` int DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `spec_name` (`spec_name`,`item_name`),
  KEY `idx_ssi_spec` (`spec_name`)
) ENGINE=InnoDB AUTO_INCREMENT=157 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
