DROP TABLE IF EXISTS `salary_view_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `salary_view_logs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `worker_name` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工人姓名',
  `month` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '查看的月份（空=全部未付）',
  `viewed_at` datetime DEFAULT NULL COMMENT '查看时间',
  PRIMARY KEY (`id`),
  KEY `idx_view_time` (`viewed_at`),
  KEY `idx_view_worker` (`worker_name`)
) ENGINE=InnoDB AUTO_INCREMENT=444 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
