CREATE TABLE `transactions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `trans_date` date NOT NULL,
  `trans_type` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '出库/入库',
  `sku_id` int NOT NULL,
  `quantity` int NOT NULL,
  `unit_price` decimal(10,2) DEFAULT '0.00',
  `amount` decimal(12,2) DEFAULT '0.00',
  `salesperson_id` int DEFAULT NULL,
  `entry_person` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `remark` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `sku_id` (`sku_id`),
  KEY `idx_date` (`trans_date`),
  KEY `idx_type` (`trans_type`),
  KEY `idx_sp` (`salesperson_id`),
  CONSTRAINT `transactions_ibfk_1` FOREIGN KEY (`sku_id`) REFERENCES `product_skus` (`id`),
  CONSTRAINT `transactions_ibfk_2` FOREIGN KEY (`salesperson_id`) REFERENCES `salespersons` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=261 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
